mapper.select:


    inner join sys_user u on u.user_name = dinspectiondayinfo.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    dinspectiondayinfo.del_flag = '0'
     and dinspectiondayinfo.day_id = #{dayId}
     and dinspectiondayinfo.equipment_id = #{equipmentId}
     and dinspectiondayinfo.img = #{img}


${params.dataScope}
